WordHunterWoW_QuestDataByFlavor = WordHunterWoW_QuestDataByFlavor or {}
WordHunterWoW_QuestDataByFlavor.classic = WordHunterWoW_QuestDataByFlavor.classic or {}
WordHunterWoW_QuestDataByFlavor.classic.enUS = WordHunterWoW_QuestDataByFlavor.classic.enUS or {}
local quests = WordHunterWoW_QuestDataByFlavor.classic.enUS
quests[6503] = { title = "Ashenvale Outrunners", description = "We received reports that Ashenvale outrunners left Silverwing Outpost not long ago, and now sneak near our territories in the forest.  We don't want them gathering intelligence on our defenses!\n\nSneak through the forests south of our post here and east of the Alliance outpost of Silverwing.  Find and slay the outrunners, then return to me.", objectives = "Kill 9 Ashenvale Outrunners, then return to Kuray'bin at Splintertree Outpost.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6504] = { title = "The Lost Pages", description = "I just picked up this shredder from Ratchet and I was on my way back to the Warsong Lumber Camp, where I am supposed to be on duty. I was given a manual on how to operate the shredder, but on the trip back, a huge gust of wind blew it from my hands. The pages went everywhere, and all I was left with was the cover.\n\nThe pages could be just about anywhere by now, I suppose... but I don't know how to use the shredder without them! Will you find them for me?", objectives = "Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6521] = { title = "An Unholy Alliance", description = "Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King.\n\nHis presence there does explain much of what we've discovered about the area--some of the quilboar have grown frightfully powerful while showing signs of the Plague in their own way. Truly that must be a sign of some sort of deal they've struck.\n\nFind Malcin and slay him, $N. Return to me after the deed is done.", objectives = "Bring Ambassador Malcin's Head to Varimathras in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6522] = { title = "An Unholy Alliance", description = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin", objectives = "Take the Small Scroll to Varimathras in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6523] = { title = "Protect Kaya", description = "Thank you for rescuing me! We must leave quickly before they discover that I am free. Please escort me to Camp Aparaje. From there, I know my way.\n\nMy father, Makaba Flathoof, will be desperate to know that I am safe.", objectives = "Escort Kaya Flathoof to Camp Aparaje, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6541] = { title = "Report to Kadrak", description = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.", objectives = "Report to Kadrak at the watch tower in northern Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6542] = { title = "Report to Kadrak", description = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.", objectives = "Report to Kadrak at the watch tower in northern Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6543] = { title = "The Warsong Reports", description = "I recently deployed a few scouts into Ashenvale and I need a runner to take them their orders, and bring me back a report of what they have observed.\n\nYour first stop should be the Zoram'gar Outpost, along the coast to the west, at the Zoram Strand, to locate the first runner. You also need to stop at Splintertree Post, to the north, and along the road to the east, near Azshara. You will find a scout and an outrider there.\n\nGive them each a report, and from them, get an update on their findings.", objectives = "Open the Bundle of Reports.  Take the Warsong Reports to the Warsong Scout, Warsong Runner, and Warsong Outrider. Bring back the updates they give you to Kadrak at the northern watch tower in the barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6544] = { title = "Torek's Assault", description = "Hey!  $C!  Come here!\n\nMy raiders and I are about to attack the Silverwing Outpost to the west.  Our target is its leader, Duriel Moonfire.  Scouts report the outpost is defended heavily with sentinels and warriors.  The battle will be glorious!\n\nDo you want to share in the glory, $N, and aid us?  If so, then when it's over you can report our success to my superior, Ertog Ragetusk in Splintertree.\n\nWhat do you say.  Are you with us?", objectives = "Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6545] = { title = "Warsong Runner Update", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6546] = { title = "Warsong Outrider Update", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6547] = { title = "Warsong Scout Update", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6548] = { title = "Avenge My Village", description = "The Grimtotem Clan raided my village and killed most everyone. I killed all I could, but barely escaped with my life.\n\n$N, all I wish now is that more of them are dead. You will find them just to the west of here.", objectives = "Kill 8 Grimtotem Ruffians and 6 Grimtotem Mercenaries, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6561] = { title = "Blackfathom Villainy", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Bashana in Thunder Bluff, $N, please.", objectives = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6562] = { title = "Trouble in the Deeps", description = "Je'neu Sancrea is in need of aid. He is at the Zoram'gar Outpost in Ashenvale. The Night elf forest is to the north of the Stonetalon mountains. You can reach it by traveling through Windshear Crag or by heading north through Barrens. Zoram Strand is far to the west of the forest. Be careful, $N. There are forces there that will not take to your presence kindly.", objectives = "Speak to Je'neu Sancrea in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6563] = { title = "The Essence of Aku'Mai", description = "Within the beginning tunnels of Blackfathom Deeps, large sapphire clusters can be found along the cave walls. Recently it was noted that the naga were harvesting the crystals. Until it can be discerned why, I sense we should stop the naga from succeeding. The crystals have great elemental power and if used inappropriately, could make for a powerful arcane component.\n\nWill you help me, $N? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.", objectives = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6564] = { title = "Allegiance to the Old Gods", description = "Some poor handwriting is scrawled on the crumpled up note:\n\n\"Yes, tell all the priestesses to bring the crystals to me. The water elemental spirits are strong within them and they will aid our aquamancers greatly in their own summonings.\n\nBy controlling the power within the crystals, we will appease Aku'Mai. One day we will have enough power to bring Aku'Mai back to us and the world will return to its greatest era! An era of rule by the Old Gods!\"", objectives = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6565] = { title = "Allegiance to the Old Gods", description = "This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated. This Lorgus cannot be allowed to succeed. You must stop him, $N. I cannot do it myself--I am too weak.\n\nGo into Blackfathom Deeps, find him, and kill him. Return to me here at Zoram'gar when it's done.", objectives = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6566] = { title = "What the Wind Carries", description = "It is good to see you again, $N. The wind carries with it news from the Eastern Kingdom.\n\nSit, listen. ", objectives = "Listen to Thrall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6567] = { title = "The Champion of the Horde", description = "I have received word from one of my champions that a way into the lair of the dragon may exist. You are to seek him out.\n\nRexxar wanders the desert wasteland of Desolace, traveling between Stonetalon and Feralas. He awaits your arrival.", objectives = "Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6568] = { title = "The Testament of Rexxar", description = "What do you know of illusions, $N? For you see, it is an illusion that you must create in order to circumvent the Black Flight's defenses.\n\nI know of one that may be willing to assist you in your quest of deception. She has assisted our kind in the past when she has deemed the cause worthy.\n\nIn the Western Plaguelands you will find Myranda the Hag, master illusionist - an exile of the Lordaeron alliance. Travel there and take with you this message.", objectives = "Deliver Rexxar's Testament to Myranda the Hag in the Western Plaguelands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6569] = { title = "Oculus Illusions", description = "So the $r wishes to become one of the Black Flight, eh?\n\nThe creation of the illusion you require is trivial, but the components required for the divination are quite difficult to obtain. Rexxar and the Warchief have entrusted you with this mission, so Myranda must assume you as capable.\n\nTravel to the upper citadel of Blackrock Spire and slay enough of the black dragonspawn to fill up one of your packs with their eyes.\n\nReturn to Myranda when you have gathered enough of the reagent.", objectives = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6570] = { title = "Emberstrife", description = "I have attuned this medallion with the magic necessary to create and maintain an illusion within the bounds of the den of Emberstrife.\n\nEmberstrife is an ancient drake; an old gatekeeper of Nefarian, burdened with the duty to test those dragonspawn that would ascend to the rank of elite guard to Onyxia.\n\nTravel to the Wyrmbog of Dustwallow Marsh and enter the lair of Emberstrife. Once there, put on the amulet and follow where your destiny may lead!", objectives = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6571] = { title = "Warsong Supplies", description = "We are in short supply of a few items at the Warsong lumber camp!\n\nPixel at Splintertree Post has our shipment of saw blades. It'll take a trip to Booty Bay to pick up a crate of axes from Wharfmaster Lozgil.\n\nOur shipment of oil and rope will be more difficult. The rope was pilfered by the Thistlefur and Foulweald furbolgs, and the satyrs intercepted the delivery of the oil and are now using it for detestable rituals in Night Run, Satyrnaar, and Xavian!\n\nCan you help me?", objectives = "Collect the Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil, and the Warsong Axe Shipment for Locke Okarr in Splintertree Post.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6581] = { title = "Warsong Saw Blades", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6582] = { title = "The Test of Skulls, Scryer", description = "We are Deathwing's children, whelp. Our dominance over the lesser Aspects must be enforced.\n\nIf you are truly worthy of ascension, the lesser dragonflight will wilt in your presence.\n\nFind their champions and lay waste to them in the name of our Father!\n\nTravel to Winterspring and track down the mighty blue drake, Scryer. Crush him and any of the Blue Flight that stand in your path. Tear out his skull and return it to me.", objectives = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.\n\nYou know that Scryer can be found in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6583] = { title = "The Test of Skulls, Somnus", description = "Just as our Father crushes the Aspects themselves, so too must we strive to bring chaos and destruction to their children.\n\nYou must test your battle prowess against the sleepless dreamers: The children of the Green Flight.\n\nTravel to the Swamp of Sorrows and track down Somnus, drake champion of the Green Flight. Let flow your hatred; dominate the insect... Return to me with his skull...", objectives = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6584] = { title = "The Test of Skulls, Chronalis", description = "The time watchers, children of Nozdormu - Lord of the Centuriesss...\n\nIt is three that guard the Caverns of Time, but only one that holds the interests of the Black Flight: The Time Shifter, Chronalis, favored drakeling of Nozdormu.\n\nSsstrike at this champion, a blow to make even the stoic sands of time weep. Return to me with his skull.", objectives = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6585] = { title = "The Test of Skulls, Axtroz", description = "It was over the mountains of Grim Batol that our Father raged against the combined might of the Aspects. The cowardly act of the betrayer, Alexstrasza, bought the other Aspects enough time to escape from Father's wrath.\n\nSssuch a shameful act...\n\nThe Red Flight now guards Grim Batol, their lieutenant, Axtroz, must be destroyed. Return the skull of Axtroz to me. For Father, whelp!", objectives = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6601] = { title = "Ascension...", description = "From the skulls of our enemies is shaped a medallion. You know this medallion, yesss? You have no doubt seen it worn by your elders.\n\nTake it, whelp. Return to the Spire and present it to General Drakkisath. The General will place the final enchantment upon the medallion, attuning the trinket to your spirit.\n\nYou will wear the finished medallion as a badge of honor, symbolizing your ascension to one of our most guarded ranks: Guardian to the brood mother.\n\nGo!", objectives = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6602] = { title = "Blood of the Black Dragon Champion", description = "You will pay the General a visit, yes, but not as one of the Black Dragonflight.\n\nYou see, a ceremony is merely another term for blood letting to the Black Flight.\n\nThe latent amulet merely needs the blood of the General in order to become active. One of their crude failsafe mechanisms.\n\nReturn to Blackrock Spire and destroy Drakkisath. Bring his blood back here and I shall activate the key to Onyxia's lair.", objectives = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6603] = { title = "Trouble in Winterspring!", description = "There's trouble in Winterspring!\n\nWhy, sure, I spend some time out in the wilds and know about these things... I'm always mighty proud to say it. I consider the hours I spend out there in the hills to be golden. Help you cultivate quick reflexes, a cool head and a keen eye...\n\nIt takes judgement, brains and maturity to appreciate the wilderness in the way that I do.\n\nNow, what was I talking about?\n\nAh yes, trouble. See Donova Snowden at the hot springs and she can tell you more.", objectives = "Find Donova Snowden near the hot springs in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6604] = { title = "Enraged Wildkin", description = "Have you noticed the abandoned camp to the south of here? It looks like the wildkin went crazy and destroyed just about everything they could find!\n\nI heard a rumor that one of the survivors of the attack is resting at Starfall Village, west of here. I'm sure curious about what happened... aren't you?", objectives = "Speak with Jaron Stoneshaper at Starfall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6605] = { title = "A Strange One", description = "I just got back from Felwood, $N. On my way through, I stopped at Bloodvenom Post and I met a very odd character... She seemed intent on one thing, and I suppose I could tell you what that is, but I think she'd like to explain it to you herself.\n\nIf you're interested, head to Bloodvenom Post in western Felwood and look for Winna Hazzard.\n\nWho knows, she might need your help...", objectives = "Speak with Winna Hazzard in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6606] = { title = "A Little Luck", description = "We can always use a little luck, eh? A small advantage is all it takes to turn things in your favor...\n\nI happened to make the acquaintance of a rather eccentric witch doctor some time back. She made me a lucky charm... for a price. Believe me, though, it was well worth it!\n\nMaybe you'd be interested in one of your own? See Witch Doctor Mau'ari in Orgrimmar. I'm not giving mine up!", objectives = "Speak with Witch Doctor Mau'ari in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6607] = { title = "Nat Pagle, Angler Extreme", description = "Can't say I really enjoy fishin' much. Figure I been at it for a good 20 or 30 years now.\n\nI reckon people are driven to do what they do for different reasons.\n\nNow, I'm not saying you need to fish for 30 years or catch every fish in the sea to become a master fisherman. I reckon you just need to be determined - determined enough to sit on your duff for hours at a time, doin' nothin'.\n\nI'll tell you what, catch me a few rare fish and I'll teach you a thing or two. Here's a list:", objectives = "Nat Pagle wants you to catch the following fish:\n\nMisty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.\n\nA Sar'theris Striker from the Sar'theris Strand in Desolace.\n\nFeralas Ahi from the Verdantis River of Feralas.\n\nSavage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.\n\nReturn to Nat Pagle when you have reeled them all in!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6608] = { title = "You Too Good.", description = "Lumak no can teach $N no more. You too good! Find Lumak friend, Nat Pagle. Is human but no eat! Is Lumak friend! Nat teach you fish gooder.\n\nYou find Nat in Dustwallow Marsh, south of Humie town, Thermorosomethinglikedat. Nat probably fishing. Go now!", objectives = "You think Lumak is trying to tell you that he can no longer help you improve your fishing skill. You may want to try to find his friend, Nat Pagle, a human fishing off one of the islands south of Theramore (at least that's what you think Lumak said).", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6609] = { title = "I Got Nothin' Left!", description = "I'm a dwarf fer cryin' out loud, $g lad:missy;! I ain't been designed to fish! I mean look at me! I'm practically made outta stone.\n\nI got nothin' left - ye tapped me out. I've taught ye all I know, flipflop!\n\nDon't ye get it? Ah, fine. I got an ol' friend over on Kalimdor who can help ye out. 'Is name be Nat Pagle, a fine lad. Find him on the islands south o' Theramore. Git goin'!", objectives = "Travel to Kalimdor, to the coastal city of Theramore. From there you must search for an island, south of the main town. Nat Pagle awaits your arrival!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6610] = { title = "Clamlette Surprise", description = "Ever heard of a clamlette? Of course you haven't! It's my latest and greatest culinary masterpiece. Oh, $N, just thinking about a clamlette makes my mouth water.\n\nUnfortunately, I'm all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I'll teach you the finer points of exotic cuisine and I'll even throw in a couple of clamlettes to boot! Deal??\n\nHere's what I need:", objectives = "Dirge Quikcleave wants you to get the following items:\n\n12 Giant Eggs. You will find those on the Rocs wandering Tanaris or any other species of large bird.\n\n10 pieces of Zesty Clam Meat. You can find those in clams, naturally!\n\n20 pieces of Alterac Swiss. Get thee to a cheesery!\n\nGather all of the items and return to Dirge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6611] = { title = "To Gadgetzan You Go!", description = "How you expect Zamja teach you anything? You got all of Zamja's cooking mojo and still you crave more!\n\nZamja can't help. Fat $r needs to go to Gadgetzan. You find a little goblin named Dirge there - he help you, fatty.\n\nWhen you become big cook on the block, you come back and teach Zamja, ok? Now go!", objectives = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6612] = { title = "I Know A Guy...", description = "I can tell by yer cooking spoon that ye know what yer doin'. Unfortunately, I can't teach ya nothin'.\n\nLuckily fer ye, I know a guy. He's a goblin and probably the best cook on Kalimdor.\n\nAyep, that's the bad news, $g lad:missy; - ye got to travel to Kalimdor. Git to Gadgetzan and find Dirge Quikcleave. He'll set ya straight.", objectives = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6621] = { title = "King of the Foulweald", description = "$N, another tribe of Furbolgs,  the Foulweald, live southeast of Astranaar.  They are not as many as the Thistlefur, but their ferocity poses a future threat.  With a show of force, we can remove that threat.\n\nTake this banner, go to the Foulweald village and place it on their totem mound.  They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe.  Bring me the totem he carries.\n\nGather your allies, $N.  This is no task for a single $c.", objectives = "Place Karang's Banner on the Foulweald Totem Mound.  Do not let the furbolgs destroy the banner.  Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6622] = { title = "Triage", description = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Horde Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nTriage bandages will be supplied.\n\nGood luck, doctor.", objectives = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.\n\nRemember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6623] = { title = "Horde Trauma", description = "Doctor $N, I presume. It is a pleasure to see you again.\n\nI have some wonderful news for you! Doctor Gregory Victor, chief physician of Horde Trauma has made a personal request for you to join him at Hammerfall. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great Doctor Gregory Victor! Do not squander this opportunity!", objectives = "Travel to Hammerfall in the Arathi Highlands and speak with Doctor Gregory Victor about joining the ranks of Horde Trauma.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6624] = { title = "Triage", description = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Alliance Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nGood luck, doctor.", objectives = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.\n\nRemember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6625] = { title = "Alliance Trauma", description = "Doctor $N, I presume. It is a pleasure to see you.\n\nI have some wonderful news for you! Gustaf VanHowzen, chief physician of Alliance Trauma has made a personal request for you to join him at Theramore. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great doctor, Gustaf VanHowzen! Do not squander this opportunity, doctor!", objectives = "Travel to Theramore in the Dustwallow Marsh and speak with Doctor Gustaf VanHowzen about joining the ranks of Alliance Trauma.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6626] = { title = "A Host of Evil", description = "The Forsaken do not pass on their... illness... from what I have seen. This diplomat seems to be granting undeath to would-be followers. I am beginning to think he is one of the Scourge.\n\nFor now, my concern is not with him though, it's with the growing ranks around him. They creep from the shadows daily, almost begging him for more power.\n\nI'm not powerful enough to fight them on my own, $N. What do you say? Are you up for some hunting?", objectives = "Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6627] = { title = "Test of Lore", description = "You have brought me the book, and now it is time for your question. Are you ready?\n\nTime is not an issue, $c, so do not feel pressured. You may take as long as you like to answer.", objectives = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6628] = { title = "Test of Lore", description = "So the time is once again upon us. As a student of lore, you have shown great tenacity by undertaking my task.\n\nAnd so now I offer you your question. If you are ready, speak to me again, and take all the time you need, $N--there is no pressure to answer quickly.", objectives = "Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6629] = { title = "Kill Grundig Darkcloud", description = "$N, you've done a fine job killing Grimtotem. If you dare, Grundig Darkcloud and his personal band of brutes is by far the worst of the lot. He was the one who led the brutal attack on my village.\n\nYou will find him in Grimtotem Post a bit further up the path to the west. Kill him, and I will be forever grateful.", objectives = "Kill Grundig Darkcloud and 6 Grimtotem Brutes, and return to Makaba Flathoof near the southeastern edge of Stonetalon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6641] = { title = "Vorsha the Lasher", description = "Vorsha the Lasher... the fiendish hydra that roams the seas...\n\nShe has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path.\n\nBut I am ready, $N. I have prepared to best the hydra and end these attacks on Zoram'gar.\n\nThe naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger.\n\nWe will need help, so be sure to bring some strong allies.", objectives = "Keep Muglash safe as he travels to the brazier. Help him by putting the brazier out, then protect him as you fight against the Naga.\n\nIf you are successful, return to the Zoram'gar Outpost and inform the Warsong Runner of the death of Vorsha the Lasher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6642] = { title = "Favor Amongst the Brotherhood, Dark Iron Ore", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6643] = { title = "Favor Amongst the Brotherhood, Fiery Core", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6644] = { title = "Favor Amongst the Brotherhood, Lava Core", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6645] = { title = "Favor Amongst the Brotherhood, Core Leather", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6646] = { title = "Favor Amongst the Brotherhood, Blood of the Mountain", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6661] = { title = "Deeprun Rat Roundup", description = "Avast ye scallywag. Arrrr... Arrrr ye looking fer work? We gots a serious rat problem down here an' not enough hands on the poop deck.\n\nWhat do ye say? All ye needs to do is take this here rat catchin' flute and play the melody around the vermin. They'll follow ye to the ends of the world!\n\nJust capture five of the little buggers and bring em back here. We needs em alive.\n\nArrrrr...", objectives = "Capture 5 Deeprun Rats by using the Rat Catcher's Flute. Lead the rats back to Monty. Don't forget to turn in the flute when you're finished.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6662] = { title = "Me Brother, Nipsy", description = "Me brother, Nipsy, runs a rat kabob operation on the other side of Deeprun. Ye needs to take this here crate o' rats to him before they go bad. Get a move on!\n\nYe have ridden a tram before, aye? It's easy. Just step aboard when she arrives and enjoy the ride. An' keep yer arms and legs inside durin' the ride, lest ye be peglegged fer life.", objectives = "Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6681] = { title = "The Manor, Ravenholdt", description = "$N,\n\nRavenholdt has taken an interest in you, young thief. We have been watching. Your style is a bit awkward but nothing we couldn't fix.\n\nShould you be prepared to embark on a career as a disciple of Master Ravenholdt and member of the Assassin's League, you have only to bring the Seal of Ravenholdt (attached to this letter) to Ravenholdt Manor.\n\nYour first task is to find the manor, hidden away in the hills of Hillsbrad and demonstrate your cunning.\n\nRegards,\n\nFahrad", objectives = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\n\nYour cunning will be tested along the way. Be prepared.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6701] = { title = "Syndicate Emblems", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6721] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", objectives = "Speak with Dazalar in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6722] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", objectives = "Speak with Dazalar in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6741] = { title = "More Booty!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6761] = { title = "The New Frontier", description = "I have relegated my second, Mathrengyl Bearwalker, to deal with Moonglade's call for aid.  Speak to him on this matter - NOT me.\n\nLet me give you some... friendly... advice.  It is I who led us out of the darkness - NOT the Cenarion Circle in Moonglade - when all was lost for our race.  Teldrassil gives us all new life!  They would have you believe otherwise, and to believe their propaganda would be a fool's task.\n\nI'll leave it to you to decide whether or not you're a fool.", objectives = "Speak with Mathrengyl Bearwalker at the Cenarion Enclave of Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6762] = { title = "Rabine Saturna", description = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris... and even further west of Un'Goro.  You should find him in Nighthaven, the main village of Moonglade.\n\nWhile your work will no doubt be of tremendous benefit to us all, I advise you to tread gingerly.  There are tensions between Darnassus and Moonglade... ones that may grow over the course of time.", objectives = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6781] = { title = "More Armor Scraps", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6801] = { title = "Lokholar the Ice Lord", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6804] = { title = "Poisoned Water", description = "A force of elemental scouts was sent to the eastern plaguelands of Lordaeron, and the disease of that place twisted and infected them.  The Waterlords cannot allow this affront to our purity!\n\nTake this vial.  In it is a quantity of one aspect of Neptulon.  If used on the plagued elementals it will fight the poison within their bodies and cure them!  But their inner conflict will drive them into a surging madness.\n\nDefeat the discordant surges and bring me their bracers of binding.", objectives = "Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands.  Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6805] = { title = "Stormers and Rumblers", description = "We, the elementals of water, wage war with those beings of the lesser elements.  If you are truly our ally in this conflict, then show me your conviction!\n\nFar to the south, in the desert land of Silithus, the servants of air and earth scurry in a corner of rock named the Crystal Vale.  They protect items of power from smaller beings, mortals, and although I do not know why they do this, I wish to foil their efforts.\n\nGo to the Crystal Vale in Silithus and defeat our enemies, then return to me.", objectives = "Kill 15 Dust Stormers and 15 Desert Rumbers and then return to Duke Hydraxis in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6821] = { title = "Eye of the Emberseer", description = "You have shown me that you can defeat our enemies and perform missions to further the cause of the Waterlords.  But until now you have only faced lesser foes... if pitted against a powerful enemy, can you prevail?\n\nThat is your new task.\n\nHigh up in Blackrock Spire the orcs have captured a servant of fire, the Pyroguard Emberseer.  Find his place of imprisonment, slay his captors, and then slay the emberseer.  Bring me his eye and it will show me your worth.", objectives = "Bring the Eye of the Emberseer to Duke Hydraxis in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6822] = { title = "The Molten Core", description = "$n, perhaps it is time to give you a real test.  Are you ready?\n\nAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.\n\nGo to the Molten Core, $N.  Show me you have the strength and the will to defeat what you find there.\n\nAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live.", objectives = "Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6823] = { title = "Agent of Hydraxis", description = "If you truly wish an allegiance with us, then I invite you to wage war on our foes, the servants of air and earth and fire.  Each defeat you heap upon them will weaken their foothold here, and further prove your adherence to our cause.\n\nThe campaign will be long, but if you persevere then your glory and honor will be great.", objectives = "Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6824] = { title = "Hands of the Enemy", description = "$N, your service is of great value to us, so we are reluctant to send you on this last mission for we do not want to lose such a useful agent.\n\nBut its success would further our war efforts tremendously and... it was deemed worth risking you.\n\nWe want these captains in the Molten Core destroyed: Lucifron, Sulfuron, Gehennas and Shazzrah.  Kill them and bring me their hands!\n\nThis task will take every resource you possess, $N, but if can do it then the Firelords will be dealt a terrible blow.", objectives = "Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6825] = { title = "Call of Air - Guse's Fleet", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6826] = { title = "Call of Air - Jeztor's Fleet", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6827] = { title = "Call of Air - Mulverick's Fleet", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6844] = { title = "Umber, Archivist", description = "There's plenty to do here still, but I think taking this back to the Circle for analysis is key.  Trust me - the work will still be here once this is all said and done.  If it's a journal inside this sticky chitin, then the Circle would finally have a window into the past!\n\nTake this to the Circle's archivist in Nighthaven.  His name is Umber, and the man's brilliant.  Touched, sure, but brilliant nonetheless!  Umber's salvaged tomes in far worse shape than this.  If it can be saved, he can do it.", objectives = "Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6845] = { title = "Uncovering Past Secrets", description = "Anyway, you should check back with me relatively soon... that is if you want to know what was in here.  As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you.\n\nIn the meantime, I'd check in with the den mother of this little bear camp, Rabine.  No doubt he'll want to know what crazy antics you've been up to.  Never leave the den mother waiting, $N... that is, unless you want to be doused in honey.\n\nIt's happened, trust me.", objectives = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6846] = { title = "Begin the Attack!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6847] = { title = "Master Ryson's All Seeing Eye", description = "Your war in the heart of Alterac means nothing to the Syndicate, $c. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>", objectives = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6848] = { title = "Master Ryson's All Seeing Eye", description = "Your war in the heart of Alterac means nothing to the Syndicate, $c. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>", objectives = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6861] = { title = "Zinfizzlex's Portable Shredder Unit", description = "I'm as anxious as you are to try out my portable shredder unit, $r, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.", objectives = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6862] = { title = "Zinfizzlex's Portable Shredder Unit", description = "I'm as anxious as you are to try out my portable shredder unit, $r, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.", objectives = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6881] = { title = "Ivus the Forest Lord", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6901] = { title = "Launch the Attack!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6921] = { title = "Amongst the Ruins", description = "The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.\n\n$N, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!", objectives = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6922] = { title = "Baron Aquanis", description = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.", objectives = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6941] = { title = "Call of Air - Vipore's Fleet", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6942] = { title = "Call of Air - Slidore's Fleet", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6943] = { title = "Call of Air - Ichman's Fleet", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6961] = { title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6962] = { title = "Treats for Great-father Winter", description = "Hey, can you do Greatfather Winter a favor, um, little $g boy : girl;?\n\nNot to needlessly talk about myself in the third person, but Greatfather Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Greatfather and fetch some for me?", objectives = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6963] = { title = "Stolen Winter Veil Treats", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains, and that's where our man went to look for it.\n\nSee if both are out there, safe and sound!", objectives = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6964] = { title = "The Reason for the Season", description = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Sagorne Creststrider.  I'm sure he'll be surprised that someone cares about history rather than getting presents.", objectives = "Speak with Sagorne Creststrider in the Valley of Wisdom of Orgrimmar about the Feast of Winter Veil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6981] = { title = "The Glowing Shard", description = "The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.\n\nMaybe you should see if anyone in Ratchet can tell you more about this strange shard.", objectives = "Travel to Ratchet to find someone that can tell you more about the glowing shard.\n\nThen, deliver the shard as you are directed.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6982] = { title = "Coldtooth Supplies", description = "The Coldtooth mine is a storage depot for the Horde.  I can't stomach the food they give their troops, and the state of their arms and armor is atrocious!  But... in times like these when supplies are so important, we can use what they have.\n\nEnter the Coldtooth mine and bring me back their supplies.  That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors.\n\nGood luck, $N.  The mine is to the distant south, deep in Horde territory.", objectives = "Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6983] = { title = "You're a Mean One...", description = "A c-c-creature called \"The Abominable Greench\" is the one w-w-who stole our shipment of t-t-treats, $N.  Be c-c-careful though!  He is t-t-the one who turned me into this s-s-snowy mess!\n\nYou're g-g-gonna need some help in f-f-facing him.  I've seen him w-w-wander all around where the y-y-yeti are; he's s-s-surely here s-s-somewhere!  F-f-find the treats $N, take them b-b-back to Smokywood Pastures in Orgrimmar, and t-t-tell them I n-n-need to be unfrozen!", objectives = "Locate and return the Stolen Treats to Kaymard Copperpinch in Orgrimmar.  It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6984] = { title = "A Smokywood Pastures' Thank You!", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, $N.  For that, we'd like to offer you a special gift... presented by none other than Great-father Winter himself!\n\nPlease, speak with Great-father Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", objectives = "Speak with Great-father Winter in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6985] = { title = "Irondeep Supplies", description = "The Stormpike dwarves are using the Irondeep mine as a storage depot.  I want you to raid that mine and bring me its supplies.  This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment!\n\nBe wary, $N.  The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.", objectives = "Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7001] = { title = "Empty Stables", description = "The war in the valley has taken its toll on our soldiers. We must revitalize our forces!\n\nIf we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle.\n\nTake this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable.\n\nWhen we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.", objectives = "Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master. Speak with the Frostwolf Stable Master to earn credit for the capture.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7002] = { title = "Ram Hide Harnesses", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7003] = { title = "Zapped Giants", description = "I'm going to have to do something about the giants if I stay out here!  They're certainly not good for business, now are they?\n\nI've been working on a variant of a gnomish shrinking ray, but I'm using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I'd like for you to try it out on any of the giants in Feralas.  You should find miniaturization residue on them after you shrink them - bring me back some!", objectives = "Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form.  Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7021] = { title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7022] = { title = "Greatfather Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
