quests[7506] = { title = "The Emerald Dream...", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7507] = { title = "Foror's Compendium", description = "You have uncovered something of great importance. This book is unlike any that you have seen.\n\nIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible.", objectives = "Return Foror's Compendium of Dragon Slaying to the Athenaeum.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7508] = { title = "The Forging of Quel'Serrar", description = "If you wish to take on this task, present Lydros with the dull blade.", objectives = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7509] = { title = "The Forging of Quel'Serrar", description = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.\n\nSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.\n\nPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.", objectives = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7541] = { title = "Service to the Horde", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7562] = { title = "Mor'zul Bloodbringer", description = "$N, your delvings into the dark arts are deep.  Your mastery over otherworldly denizens has grown so strong... perhaps you are ready to bind to you one of the infamous dreadsteeds.\n\nThe ritual to summon the beast from its home requires great power and resources, but if you desire to dominate that epic mount, then speak with Mor'zul Bloodbringer.  He is camped near the Altar of Storms in the Burning Steppes.\n\nGo, $N.  This quest will be perilous, but a Warlock of your stature does not shy from danger!", objectives = "Speak with Mor'zul Bloodbringer in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7563] = { title = "Rage of Blood", description = "The dreadsteeds dwell on another world, on the fiery Plains of Xoroth, and to bind one of those famed beasts you must invoke powerful glyphs.  I can scribe the glyphs on a parchment for you, but first I will need a special ink.\n\nIn distant Winterspring there dwells a race of owl beasts.  Once pure creatures, they were turned mad by the demonic emanations of the Darkwhisper Gorge and now roam the snows in a frenzy.\n\nTheir blood is what I need to ink your parchment.  Bring it to me.", objectives = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7564] = { title = "Wildeyes", description = "My servant, Gorzeeki, is an alchemist of some skill.  He can prepare the ink I will need for your parchment.  I gathered together the blood you acquired; take it to Gorzeeki so that he can begin his work.", objectives = "Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7581] = { title = "The Prison's Bindings", description = "You must retrieve bindings for the prison of the Doomguard from lesser demons.\n\nThe blood of the Wildspawn satyr that occupy Dire Maul should do nicely. The coagulated blood will bond the Hederine shards and power the crystal prison.", objectives = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7582] = { title = "The Prison's Casing", description = "The Hederine demons that occupy the foothills of Mount Hyjal secrete powerful fel poisons, which if left to mature, harden into a dense anti-magic crystal. These crystals have come to be known as Tears of the Hederine.\n\nNot even the immense power of a Doomguard could break the walls of a prison constructed from this material.\n\nTravel to Darkwhisper Gorge in Winterspring and recover the Tears.", objectives = "Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7583] = { title = "Suppression", description = "The prison is ready. Now for the most difficult portion of this task.\n\nYou must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison.\n\nBe warned! A Doomguard is a cunning and lethal adversary and will seek to destroy you as you begin the ritual of imprisonment. It will flail wildly in its attempts to escape imprisonment.\n\nIt will focus on nothing but you, $N. Because of this, I must recommend that you take companions capable of keeping you alive!", objectives = "Venture forth into the Tainted Scar and locate a Doomguard Commander.\n\nUse the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.\n\nShould you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7601] = { title = "What Niby Commands", description = "If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.\n\nMy imp, Impsy, shall set you on your way.", objectives = "Speak with Impsy in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7602] = { title = "Flawless Fel Essence", description = "If you're going to reanimate Kroshius, you're going to need Fel fire. I can make Fel fire but it's going to require some components.\n\nYou need to bring me flawless Fel essences from three distinct regions of the world.\n\nThe Legashi Satyrs of Azshara will have the first essence type; the Jaedenar legionnaires of Jaedenar the second type and the felguard sentries of the Blasted Lands the third.\n\nBring me back one of each essence type and I will create the Fel fire, allowing you to reanimate Kroshius.", objectives = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\n\nThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\n\nRecover the Flawless Fel Essences and return  to Impsy in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7603] = { title = "Kroshius' Infernal Core", description = "Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal.\n\nAt this point, I fully expect him to kill you and any friends that you may have brought along - and trust me, you will want to bring along some friends.\n\nIf by some miracle you happen to kill Kroshius, take his infernal core and return it to Niby.", objectives = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\n\nReturn Kroshius' Infernal Core to Niby the Almighty in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7604] = { title = "A Binding Contract", description = "The undersigned hereby declares that the Sulfuron ingot they are delivering to the Thorium Brotherhood (TB Ltd.) is genuine and not a facsimile thereof. The undersigned also acknowledges that any harm that should come to $g him:her; as a result of attempting to build, forge, find, create, sell, or eat Sulfuras, is not the responsibility or fault of TB Ltd.\n\nBy signing this contract, you are agreeing to all terms listed herein.\n\n_________________\n\nSignature", objectives = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7621] = { title = "A Warning", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7622] = { title = "The Balance of Light and Shadow", description = "You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.\n\nThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.\n\nEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, $N.", objectives = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7623] = { title = "Lord Banehollow", description = "Mor'zul says that you want to open a portal to Xoroth.  To do that, you'll need Xorothian stardust.  That's not easy to find on Azeroth!\n\nThere is one being who might have some: Lord Banehollow in Jaedenar, the seat of the Shadow Council!  Speak with him and he might part with the stardust.\n\nBut if you're going to Jaedenar, then you'll need to cloak yourself in the Shadow Council's own flavor of evil.  That will require some of my shadowy potions, and that will cost you...", objectives = "Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.\n\nUse the potions to travel through Jaedenar, and speak with Lord Banehollow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7624] = { title = "Ulathek the Traitor", description = "You wish to enter my good graces?  Then kill for me.\n\nMy servant, Ulathek, is pathetic how he grovels before me, all the while plotting with Lord Hel'nurath on Xoroth.  Hel'nurath plans to usurp my power here, and Ulathek is his spy...\n\nProve that you serve me and not my rivals.  Confront Ulathek in his quarters, in the Shadow Hold to the west.  Tell him that I know his secret and watch as fear grips him.  Then, bring me the traitor's heart!", objectives = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7625] = { title = "Xorothian Stardust", description = "So you come to me seeking Xorothian stardust?  You wish to open a portal to Xoroth, the domain of Hel'nurath my rival?  Perhaps you plan to steal from him one of his precious dreadsteeds?\n\nVery well.  My servant Ur'dan has a supply of Xorothian stardust.  You may obtain it from him... if you can pay the price.", objectives = "Purchase Xorothian Stardust from Ur'dan.  Bring it to Gorzeeki Wildeyes in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7626] = { title = "Bell of Dethmoora", description = "A Bell of Dethmoora, named after the late warlock Dethmoora Darkeyes, is one of the three tools needed to create a Circle of Greater Summoning.  When properly atuned with the Wheel and the Candle, these items conduct vast stores of arcane power.\n\nMy servant Gorzeeki can construct such a bell, but to do so he will need a large supply of elixirs of shadow power.  Procure the elixirs from an alchemist and bring them to Gorzeeki.", objectives = "Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7627] = { title = "Wheel of the Black March", description = "A Wheel of the Black March contains and directs the violent energies required for the Circle of Greater Summoning.  For Gozeeki to construct a wheel, he will need both large brilliant shards from an enchanter, and dark iron ore from a master miner.\n\nAcquire these and bring them to my servant.", objectives = "Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7628] = { title = "Doomsday Candle", description = "A Doomsday Candle stores fire and directs it at those who would disrupt your ritual.  When creating your Circle of Greater Summoning, if your candle is lit then any wayward demons will be burned by its flames!\n\nContaining that fire is not easy, and requires the essence within the scales of a black dragon.  Acquire those scales from a skinner and bring them to Gorzeeki Wildeyes.", objectives = "Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7629] = { title = "Imp Delivery", description = "There is one more process required for Mor'zul's parchment; I need paper infused with Xorothian stardust.  And... I'm afraid I can't do that here.  I don't have the equipment!\n\nThere is an alchemy lab, however, with everything needed.  It's in the Scholomance, on the isle of Caer Darrow in the Plaguelands.\n\nI can't make the trip, but here - take this jar.  There's an imp inside who is quite clever.  Let him out at the alchemy lab and he'll infuse the parchment.", objectives = "Bring the Imp in a Jar to the alchemy lab in the Scholomance.  After the parchment is created, return the jar to Gorzeeki Wildeyes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7630] = { title = "Arcanite", description = "Now that the Bell, Wheel and Candle are made, I should make a black lodestone.  During your ritual, you'll need that lodestone to maintain the other ritual objects if they should fail.\n\nTo make the lodestone, I require arcanite.  Do you have any?  If not, then... you'll have to get the arcanite from an alchemist.\n\nReturn to me when you have the arcanite, and then I'll make the black lodestone.", objectives = "Bring 3 Arcanite Bars to Gorzeeki in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7631] = { title = "Dreadsteed of Xoroth", description = "All the preparations are made.  Now, you must perform the ritual to create a Circle of Greater Summoning, then use the parchment infused with Xorothian stardust... to open a portal to Xoroth.\n\nI have written the instructions for the ritual onto a scroll.  Study it closely, for you must perform each step exactly if you wish to succeed.\n\nFortune to you, $N.  And may the souls of your enemies swiftly find their way into your shard pouch.", objectives = "Read Mor'zul's Instructions.  Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7632] = { title = "The Ancient Leaf", description = "The epidermis of the leaf glows a bright green. The surface is extremely rugose, exposing several veins and wrinkles.\n\nIf you had to take a guess, you would say this leaf came from something ancient and powerful.\n\nMaybe you should find the original owner of this leaf?", objectives = "Find the owner of the Ancient Petrified Leaf. Good luck, $N; It's a big world.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7633] = { title = "An Introduction", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7634] = { title = "Ancient Sinew Wrapped Lamina", description = "Greetings, $c. I am Hastat, Ancient of Lore. I hold knowledge lost eons ago.\n\nWith the proper binding, one of my leaves can serve as a quiver the likes of which has not been seen in 10,000 years. A quiver that when accompanied by a bow of Ancients, could grant untold powers.\n\nReturn here with sinew from an adult blue dragon and this quiver shall be yours.", objectives = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7635] = { title = "A Proper String", description = "Vartrus may offer you the stave to create a bow of Ancients but only I can enchant the string required to complete the bow.\n\nIt is a simple task, puny one. Slay a mature black dragon and remove the sinew from its bones. Return that sinew to me and I shall enchant the material into an almost indestructible bow string.", objectives = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7636] = { title = "Stave of the Ancients", description = "Agents of the Burning Legion are still active in our world, $c. These agents corrupt all that they touch. Nature wilts and weeps in their presence.\n\nYou must track down these demonic corrupters and destroy them, $N. Be warned, you must engage them by yourself or they will flee. As long as you are alone, they will try and destroy you. You must strike at them, turning their arrogance into misery.\n\nI grant you a piece of my bark, the inscriptions shall lead you to your targets. Retrieve their heads.", objectives = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7637] = { title = "Emphasis on Sacrifice", description = "In order to prepare yourself for this task, you must first show due sacrifice and judgment... with an emphasis on sacrifice.\n\nYou must acquire High Priest Rohan's exorcism censer for your task.  Even though its use will be for good and just reasons, due compensation must be given for it.\n\nProceed to Ironforge and speak with the High Priest.  By bringing ample coin with you to help offset the loss of his censer, it will show your due sacrifice.\n\nGo now $N, time is of the essence.", objectives = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer.  You will need to make a donation of 150 gold in order to secure it.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7638] = { title = "Lord Grayson Shadowbreaker", description = "The time has come, $N, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.\n\nSpeak with Lord Grayson Shadowbreaker here in Stormwind's Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin's most trusted mount, but the tasks before you to acquire one of your own.\n\nI wish you the best in this trial.  For the Light, noble $G brother : sister;!", objectives = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7639] = { title = "To Show Due Judgment", description = "With my blessings, take the censer.  I myself have used it in several exorcisms, and it should serve you well for the arduous tasks that lie ahead.\n\nReturn now to Lord Grayson Shadowbreaker in Stormwind, $N.  Your quest continues with him.", objectives = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
